export default "const app=document.querySelector('#app');let state={token:localStorage.getItem('chatlk_token'),user:JSON.parse(localStorage.getItem('chatlk_user')||'null'),chats:[],active:null,messages:[]};const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[c]));const api=async(path,opts={})=>{const r=await fetch('/api'+path,{...opts,headers:{'content-type':'application/json',Authorization:`Bearer ${state.token}`,...opts.headers}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');return d};\nfunction auth(){app.innerHTML=`<section class=\"auth\"><div class=\"auth-card\"><div class=\"brand\"><div class=\"brand-mark\">✦</div><div><h1>ChatLK</h1><p>Closer conversations, everywhere</p></div></div><h2>Welcome back.</h2><p>Private, realtime messaging designed for Sri Lanka.</p><form id=\"auth-form\"><label class=\"field\"><span>PHONE OR USERNAME</span><input name=\"identifier\" placeholder=\"+94 77 123 4567\" required/></label><label class=\"field\"><span>PASSWORD</span><input type=\"password\" name=\"password\" placeholder=\"At least 8 characters\" required/></label><button class=\"primary\">Sign in to ChatLK</button></form><div class=\"switch\">New here? <button class=\"link\" id=\"register\">Create an account</button></div></div></section>`;document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify(b)});state.token=d.token;state.user=d.user;localStorage.setItem('chatlk_token',d.token);localStorage.setItem('chatlk_user',JSON.stringify(d.user));render()}catch(err){alert(err.message)}};document.querySelector('#register').onclick=register}\nfunction register(){app.innerHTML=`<section class=\"auth\"><div class=\"auth-card\"><div class=\"brand\"><div class=\"brand-mark\">✦</div><h1>ChatLK</h1></div><h2>Join the conversation.</h2><form id=\"reg-form\"><label class=\"field\"><span>USERNAME</span><input name=\"username\" pattern=\"[A-Za-z0-9_]{3,20}\" required/></label><label class=\"field\"><span>PHONE · E.164</span><input name=\"phone\" placeholder=\"+94771234567\" required/></label><label class=\"field\"><span>DISPLAY NAME</span><input name=\"display_name\" required/></label><label class=\"field\"><span>PASSWORD</span><input type=\"password\" name=\"password\" minlength=\"8\" required/></label><button class=\"primary\">Create account</button></form><div class=\"switch\">Already a member? <button class=\"link\" onclick=\"location.reload()\">Sign in</button></div></div></section>`;document.querySelector('#reg-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.token=d.token;state.user=d.user;localStorage.setItem('chatlk_token',d.token);localStorage.setItem('chatlk_user',JSON.stringify(d.user));render()}catch(err){alert(err.message)}}}\nasync function render(){if(!state.token)return auth();const d=await api('/chats');state.chats=d.chats||[];app.innerHTML=`<div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\"><div class=\"brand-mark\">✦</div><div><h1>ChatLK</h1><p>Messages that matter</p></div></div><div class=\"search\">⌕<input placeholder=\"Search conversations\" id=\"search\"/></div><div class=\"section-label\">Your conversations</div><div id=\"chat-list\"></div><button class=\"pill\" id=\"logout\">Log out</button></aside><section class=\"main\"><div class=\"topbar\"><div class=\"peer\"><button class=\"icon-btn mobile-only\" id=\"back\">‹</button><div class=\"avatar\">${esc((state.user?.displayName||'Y')[0])}</div><div><h2>Pick a conversation</h2><span class=\"online\">● ready to connect</span></div></div><div class=\"top-actions\"><button class=\"icon-btn\">⋯</button></div></div><div class=\"messages\"><div class=\"empty\"><b>Your inbox is ready.</b>Select a conversation from the left to start messaging.</div></div><form class=\"composer\" id=\"composer\"><button type=\"button\" class=\"icon-btn\">＋</button><input name=\"text\" placeholder=\"Write a message...\" autocomplete=\"off\"/><button class=\"send\">➤</button></form></section></div>`;document.querySelector('#logout').onclick=()=>{localStorage.clear();state.token=null;render()};document.querySelector('#composer').onsubmit=send;document.querySelector('#back').onclick=()=>document.querySelector('.shell').classList.remove('chat-open');drawChats()}\nfunction drawChats(){const el=document.querySelector('#chat-list');if(!state.chats.length){el.innerHTML='<div class=\"empty\"><b>No conversations yet</b>Add a contact or create a group to get started.</div>';return}el.innerHTML=state.chats.map(c=>`<button class=\"chat-item\" data-id=\"${c.id}\"><div class=\"avatar\">${esc((c.name||'C')[0])}</div><div class=\"chat-meta\"><strong>${esc(c.name||'Direct conversation')}</strong><span>${esc(c.last_message||'No messages yet')}</span></div><span class=\"time\">now</span></button>`).join('');el.querySelectorAll('.chat-item').forEach(x=>x.onclick=()=>openChat(x.dataset.id))}\nasync function openChat(id){state.active=state.chats.find(x=>x.id===id);const d=await api(`/messages/chats/${id}/messages`);state.messages=(d.messages||[]).reverse();document.querySelector('.shell').classList.add('chat-open');const title=document.querySelector('.topbar h2');title.textContent=state.active.name||'Direct conversation';drawMessages();const protocol=location.protocol==='https:'?'wss:':'ws:';state.ws=new WebSocket(`${protocol}//${location.host}/ws?userId=${state.user?.id}&chatId=${id}&token=${state.token}`);state.ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='message'){state.messages.push(m.message);drawMessages()}}}\nfunction drawMessages(){const el=document.querySelector('.messages');el.innerHTML='<div class=\"day\">Today</div>'+state.messages.map(m=>`<div class=\"bubble ${m.sender_id===state.user?.id||m.senderId===state.user?.id?'sent':''}\"><p>${esc(m.text)}</p><small>${new Date(m.created_at||m.createdAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} ✓✓</small></div>`).join('');el.scrollTop=el.scrollHeight}\nasync function send(e){e.preventDefault();const input=e.target.text;if(!input.value.trim()||!state.active)return;if(state.ws?.readyState===1)state.ws.send(JSON.stringify({type:'message',text:input.value.trim()}));else await api(`/messages/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify({text:input.value.trim()})});input.value=''}\nrender();\n";
